1	import type Database from "better-sqlite3";
2	import { fetchCompany, fetchListings, titleMatches, type CompanySnapshot, type ListingSnapshot } from "./crustdata";
3	import { draftCaseNote, type CaseNote } from "./llm";
4	import { faultEnabled } from "./faults";
5	import { newId, stableId } from "./ids";
6	import { decideTreatment, type ListingObservation, type ReplyReading } from "./policy";
7	import { addDays, calculateScenarios, type MandateTreatment } from "./scenarios";
8	import { agencyInput, clients, evidenceFor, getAgency, inputVersion, insertEvidence, mandateInput, mandates, type CfoBindings, type ClientRecord, type MandateRecord } from "./store";
9	import { liveCfo, syncScenario, type CfoPort } from "./sync";
10	import { toolSpan, workflow } from "./telemetry";
11	
12	export const STEPS = { weekly: ["match_companies", "check_listings", "assess", "forecast", "sync_cfo"], reassess: ["assess", "forecast", "sync_cfo"] } as const;
13	export type RunKind = keyof typeof STEPS;
14	export const MAX_ATTEMPTS = 3;
15	const LEASE_SECONDS = 120;
16	
17	export interface Budget {
18	  crustdataCredits: number;
19	  modelCalls: number;
20	}
21	
22	export interface Usage {
23	  crustdataCredits: number;
24	  modelCalls: number;
25	  modelTokens: number;
26	}
27	
28	export interface RunRow {
29	  id: string;
30	  agency_id: string;
31	  kind: RunKind;
32	  status: "queued" | "running" | "retrying" | "complete" | "failed" | "partial";
33	  step: string;
34	  available_at: string | null;
35	  input_version: string;
36	  lease_owner: string | null;
37	  lease_expires_at: string | null;
38	  attempts: number;
39	  budget: string;
40	  usage: string;
41	  error: string | null;
42	  trace_id: string | null;
43	  created_at: string;
44	  updated_at: string;
45	}
46	
47	export interface Ports {
48	  fetchCompany: (domain: string) => Promise<CompanySnapshot>;
49	  fetchListings: (companyId: string, roleTitle: string, since: string) => Promise<ListingSnapshot>;
50	  draftCaseNote: typeof draftCaseNote;
51	  cfo: CfoPort;
52	}
53	
54	export const livePorts: Ports = { fetchCompany, fetchListings: (c, t, s) => fetchListings(c, t, s), draftCaseNote, cfo: liveCfo };
55	
56	export function enqueueRun(db: Database.Database, agencyId: string, kind: RunKind = "weekly", budget: Budget = { crustdataCredits: 10, modelCalls: 20 }): string {
57	  const active = db.prepare("SELECT id FROM review_run WHERE agency_id = ? AND status IN ('queued','running','retrying')").get(agencyId) as { id: string } | undefined;
58	  if (active) return active.id;
59	  const id = newId("run");
60	  db.prepare("INSERT INTO review_run (id, agency_id, kind, status, step, input_version, budget) VALUES (?,?,?,?,?,?,?)").run(id, agencyId, kind, "queued", STEPS[kind][0], inputVersion(db, agencyId), JSON.stringify(budget));
61	  return id;
62	}
63	
64	export function claimRun(db: Database.Database, owner: string): RunRow | null {
65	  return (
66	    (db
67	      .prepare(
68	        `UPDATE review_run SET lease_owner = ?, lease_expires_at = datetime('now', '+${LEASE_SECONDS} seconds'), status = 'running', updated_at = datetime('now')
69	         WHERE id = (SELECT id FROM review_run WHERE status IN ('queued','running','retrying')
70	           AND (lease_expires_at IS NULL OR lease_expires_at < datetime('now'))
71	           AND (available_at IS NULL OR available_at <= datetime('now'))
72	           ORDER BY created_at LIMIT 1)
73	         RETURNING *`
74	      )
75	      .get(owner) as RunRow | undefined) ?? null
76	  );
77	}
78	
79	function renewLease(db: Database.Database, runId: string, owner: string, step: string): void {
80	  const r = db.prepare(`UPDATE review_run SET lease_expires_at = datetime('now', '+${LEASE_SECONDS} seconds'), step = ?, updated_at = datetime('now') WHERE id = ? AND lease_owner = ?`).run(step, runId, owner);
81	  if (r.changes !== 1) throw new LeaseLostError();
82	}
83	
84	export class LeaseLostError extends Error {
85	  constructor() {
86	    super("Another worker took over this review.");
87	  }
88	}
89	
90	class BudgetError extends Error {}
91	
92	function chargeUsage(db: Database.Database, run: RunRow, delta: Partial<Usage>): void {
93	  const budget = JSON.parse(run.budget) as Budget;
94	  const usage = { crustdataCredits: 0, modelCalls: 0, modelTokens: 0, ...(JSON.parse(run.usage) as Partial<Usage>) };
95	  usage.crustdataCredits = Math.round((usage.crustdataCredits + (delta.crustdataCredits ?? 0)) * 100) / 100;
96	  usage.modelCalls += delta.modelCalls ?? 0;
97	  usage.modelTokens += delta.modelTokens ?? 0;
98	  run.usage = JSON.stringify(usage);
99	  db.prepare("UPDATE review_run SET usage = ? WHERE id = ?").run(run.usage, run.id);
100	  if (usage.crustdataCredits > budget.crustdataCredits) throw new BudgetError(`Crustdata budget for this review (${budget.crustdataCredits} credits) is used up.`);
101	  if (usage.modelCalls > budget.modelCalls) throw new BudgetError(`Model call budget for this review (${budget.modelCalls}) is used up.`);
102	}
103	
104	function evidenceExists(db: Database.Database, id: string): boolean {
105	  return Boolean(db.prepare("SELECT 1 FROM evidence WHERE id = ?").get(id));
106	}
107	
108	async function stepMatchCompanies(db: Database.Database, run: RunRow, ports: Ports): Promise<object> {
109	  const out: Record<string, string> = {};
110	  for (const c of clients(db, run.agency_id)) {
111	    const evId = stableId("ev", run.id, c.id, "company");
112	    if (!evidenceExists(db, evId)) {
113	      const snap = await toolSpan("crustdata.company_enrich", () => ports.fetchCompany(c.domain));
114	      chargeUsage(db, run, { crustdataCredits: snap.credits ?? 2 });
115	      const exact = snap.candidates.filter((x) => x.primaryDomain === c.domain && x.confidence >= 0.9);
116	      const status = exact.length === 1 ? "matched" : snap.candidates.length === 0 ? "not_found" : "ambiguous";
117	      const now = new Date().toISOString();
118	      db.transaction(() => {
119	        insertEvidence(db, {
120	          id: evId, agency_id: run.agency_id, client_id: c.id, mandate_id: null, source_type: "company_snapshot", provenance: "live", source_date: now.slice(0, 10), retrieved_at: now,
121	          summary: status === "matched"
122	            ? `Crustdata: ${exact[0].name} (${c.domain}) shows ${snap.openingsCount ?? "unknown"} open roles company-wide${trendText(snap)}. Company-level only.`
123	            : status === "ambiguous" ? `Crustdata returned ${snap.candidates.length} possible companies for ${c.domain}; none matched exactly. Match blocked until confirmed.` : `Crustdata found no company for ${c.domain}.`,
124	          payload: JSON.stringify({ candidates: snap.candidates, openingsCount: snap.openingsCount, recentTitles: snap.recentTitles, timeseries: snap.timeseries }),
125	          complete: status === "matched" ? 1 : 0,
126	        });
127	        db.prepare("UPDATE client SET match_status = ?, company_id = ?, matched_name = ? WHERE id = ?").run(status, status === "matched" ? exact[0].companyId : null, status === "matched" ? exact[0].name : null, c.id);
128	      })();
129	    }
130	    out[c.domain] = (db.prepare("SELECT match_status FROM client WHERE id = ?").get(c.id) as { match_status: string }).match_status;
131	  }
132	  return out;
133	}
134	
135	function trendText(s: CompanySnapshot): string {
136	  const pts = s.timeseries;
137	  if (pts.length < 2) return "";
138	  const last = pts[pts.length - 1];
139	  const prior = pts[Math.max(0, pts.length - 4)];
140	  return `; ${prior.openJobs} on ${prior.date} vs ${last.openJobs} on ${last.date}`;
141	}
142	
143	async function stepCheckListings(db: Database.Database, run: RunRow, ports: Ports): Promise<object> {
144	  const out: Record<string, string> = {};
145	  const byId = new Map(clients(db, run.agency_id).map((c) => [c.id, c]));
146	  for (const m of mandates(db, run.agency_id)) {
147	    const c = byId.get(m.client_id)!;
148	    if (!m.listing_seen_at) { out[m.id] = "not_checked"; continue; }
149	    if (c.match_status !== "matched" || !c.company_id) { out[m.id] = "blocked_by_match"; continue; }
150	    const evId = stableId("ev", run.id, m.id, "listings");
151	    if (!evidenceExists(db, evId)) {
152	      const since = addDays(m.listing_seen_at, -30);
153	      const snap = await toolSpan("crustdata.job_search", () => ports.fetchListings(c.company_id!, m.role_title, since));
154	      chargeUsage(db, run, { crustdataCredits: snap.credits ?? snap.listings.length * 0.03 });
155	      const hit = snap.listings.find((l) => titleMatches(l.title, m.role_title));
156	      const status: ListingObservation["status"] = hit ? "found" : snap.complete ? "not_found" : "incomplete";
157	      const now = new Date().toISOString();
158	      insertEvidence(db, {
159	        id: evId, agency_id: run.agency_id, client_id: c.id, mandate_id: m.id, source_type: "listing_check", provenance: "live", source_date: now.slice(0, 10), retrieved_at: now,
160	        summary: status === "found" ? `Crustdata still lists "${hit!.title}" (added ${hit!.dateAdded?.slice(0, 10) ?? "unknown"}).`
161	          : status === "not_found" ? `Crustdata's complete search found no listing matching "${m.role_title}" at ${c.matched_name} since ${since}. A missing listing is an observation, not a confirmed pause.`
162	          : `Crustdata's listing search for "${m.role_title}" was incomplete, so no conclusion is drawn.`,
163	        payload: JSON.stringify({ ...snap, status }),
164	        complete: snap.complete ? 1 : 0,
165	      });
166	    }
167	    out[m.id] = (JSON.parse((db.prepare("SELECT payload FROM evidence WHERE id = ?").get(evId) as { payload: string }).payload) as { status: string }).status;
168	  }
169	  return out;
170	}
171	
172	export function latestReply(db: Database.Database, caseId: string): ReplyReading | null {
173	  const r = db.prepare("SELECT id, interpretation FROM client_reply WHERE case_id = ? AND interpretation IS NOT NULL ORDER BY reply_date DESC, created_at DESC LIMIT 1").get(caseId) as { id: string; interpretation: string } | undefined;
174	  if (!r) return null;
175	  const i = JSON.parse(r.interpretation) as { outcome: ReplyReading["outcome"]; paused_until: string | null };
176	  return { outcome: i.outcome, pausedUntil: i.paused_until, replyId: r.id };
177	}
178	
179	function listingObservation(db: Database.Database, run: RunRow, m: MandateRecord): ListingObservation {
180	  const row = db.prepare("SELECT id, payload FROM evidence WHERE agency_id = ? AND mandate_id = ? AND source_type = 'listing_check' ORDER BY retrieved_at DESC LIMIT 1").get(run.agency_id, m.id) as { id: string; payload: string } | undefined;
181	  if (!row) return { status: "not_checked" };
182	  return { status: (JSON.parse(row.payload) as { status: ListingObservation["status"] }).status, evidenceId: row.id };
183	}
184	
185	async function stepAssess(db: Database.Database, run: RunRow, ports: Ports): Promise<object> {
186	  const agency = getAgency(db, run.agency_id);
187	  const byId = new Map<string, ClientRecord>(clients(db, run.agency_id).map((c) => [c.id, c]));
188	  const out: Record<string, string> = {};
189	  for (const m of mandates(db, run.agency_id)) {
190	    const c = byId.get(m.client_id)!;
191	    const caseId = stableId("case", run.agency_id, m.id);
192	    db.prepare("INSERT OR IGNORE INTO case_record (id, agency_id, mandate_id, observation, state, version) VALUES (?,?,?,?,?,0)").run(caseId, run.agency_id, m.id, "", "open");
193	    const already = db.prepare("SELECT 1 FROM decision WHERE case_id = ? AND run_id = ?").get(caseId, run.id);
194	    if (already) { out[m.id] = "kept"; continue; }
195	    const reply = latestReply(db, caseId);
196	    const policy = decideTreatment({ stage: m.stage, lastConfirmedAt: c.last_confirmed_at, cashDate: agency.cash_date, listing: listingObservation(db, run, m), reply });
197	    const ev = evidenceFor(db, run.agency_id, m.id, c.id);
198	    let note: CaseNote | null = null;
199	    if (policy.needsTask) {
200	      chargeUsage(db, run, { modelCalls: 1 });
201	      const r = await ports.draftCaseNote({ roleTitle: m.role_title, clientName: c.name, stage: m.stage, missing: policy.missing, evidence: ev.map((e) => ({ id: e.id, provenance: e.provenance, sourceDate: e.source_date, summary: e.summary })) });
202	      chargeUsage(db, run, { modelTokens: r.tokens });
203	      note = r.note;
204	    }
205	    const prev = db.prepare("SELECT version FROM case_record WHERE id = ?").get(caseId) as { version: number };
206	    const version = prev.version + 1;
207	    db.transaction(() => {
208	      db.prepare("UPDATE case_record SET observation = ?, state = ?, outcome = ?, paused_until = ?, summary = ?, version = ?, updated_at = datetime('now') WHERE id = ?").run(
209	        policy.observation, policy.needsTask ? "awaiting_confirmation" : "resolved", policy.outcome, reply?.pausedUntil ?? null, note?.summary ?? policy.observation, version, caseId
210	      );
211	      db.prepare("INSERT INTO decision (id, case_id, run_id, case_version, outcomes_considered, selected_outcome, support, missing_facts, evidence_ids, assumption_change) VALUES (?,?,?,?,?,?,?,?,?,?)").run(
212	        stableId("dec", caseId, version), caseId, run.id, version, JSON.stringify(policy.considered), policy.outcome, note?.summary ?? policy.observation, JSON.stringify(policy.missing),
213	        JSON.stringify(note?.evidence_ids ?? ev.map((e) => e.id)), assumptionChange(policy.outcome, reply?.pausedUntil ?? null)
214	      );
215	      db.prepare("UPDATE task SET status = 'superseded' WHERE case_id = ? AND status = 'open' AND case_version < ?").run(caseId, version);
216	      if (policy.needsTask && note) {
217	        db.prepare("INSERT OR IGNORE INTO task (id, case_id, case_version, question, assignee, priority_reason, due_date) VALUES (?,?,?,?,?,?,?)").run(
218	          stableId("task", caseId, version), caseId, version, note.question, c.account_manager, `USD ${(m.fee_cents / 100).toLocaleString("en-US")} fee at ${m.probability_bps / 100}% is unconfirmed: ${policy.missing.join(" ")}`, addDays(agency.cash_date, 3)
219	        );
