283	      db.prepare("UPDATE review_run SET status = 'failed', error = ?, lease_owner = NULL WHERE id = ?").run("The imported data changed after this review was planned. Start a new review.", run.id);
284	      return getRun(db, run.id);
285	    }
286	    for (const step of STEPS[run.kind]) {
