292	        db.prepare("INSERT INTO review_step (run_id, step, status, output, completed_at) VALUES (?,?,?,?,datetime('now')) ON CONFLICT(run_id, step) DO UPDATE SET status='done', output=excluded.output, completed_at=excluded.completed_at").run(run.id, step, "done", JSON.stringify(output));
293	        if (opts.crashAfterStep === step || faultEnabled(`crash_after_${step}`)) throw new SimulatedCrash(step);
294	      } catch (e) {
295	        if (e instanceof SimulatedCrash || e instanceof LeaseLostError) throw e;
296	        const message = e instanceof Error ? e.message : String(e);
297	        const attempts = run.attempts + 1;
298	        const final = attempts >= MAX_ATTEMPTS || e instanceof BudgetError;
299	        const doneSteps = (db.prepare("SELECT COUNT(*) AS n FROM review_step WHERE run_id = ? AND status = 'done'").get(run.id) as { n: number }).n;
300	        db.prepare(`UPDATE review_run SET attempts = ?, status = ?, error = ?, lease_owner = NULL, lease_expires_at = NULL, available_at = ${final ? "NULL" : `datetime('now', '+${5 * 2 ** attempts} seconds')`}, updated_at = datetime('now') WHERE id = ?`).run(
301	          attempts, final ? (doneSteps > 0 ? "partial" : "failed") : "retrying", `${step}: ${message}`, run.id
302	        );
303	        db.prepare("INSERT INTO review_step (run_id, step, status, output) VALUES (?,?,?,?) ON CONFLICT(run_id, step) DO UPDATE SET status='failed', output=excluded.output").run(run.id, step, "failed", JSON.stringify({ error: message }));
